        jdbc.sql("INSERT INTO tag_transfer"
                + " (tag_code, from_station_code, to_station_code, status, initiated_at, request_id)"
                + " VALUES (:t, :f, :to, 'PENDING', :at, :r)")
                .param("t", tagCode)
                .param("f", fromStation)
                .param("to", toStation)
                .param("at", Timestamp.from(initiatedAt))
                .param("r", requestId)
                .update(keys);
