        return jdbc.sql("SELECT " + COLUMNS + " FROM tag_transfer WHERE id = :id")
                .param("id", id)
                .query((rs, n) -> map(rs))
                .optional();
    }

    public Optional<TransferRow> findPendingByTag(String tagCode) {
