        registerTag("L-03", "ST-ALPHA");
        attach("req-b4", "L-03", "AN-2001", "ST-ALPHA", "2026-02-01T08:30:00Z");
        var animalCrossing = attach("req-b5", "L-02", "AN-2001", "ST-ALPHA", "2026-02-01T09:00:00Z");
